import { toggleNotifications } from '@/app/actions'
import { getNotificationPreference } from '@/lib/preferences'

export default function Home() {
  const { enabled } = getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

